package simshotels;

import java.util.Collections;
import java.util.HashMap;
import java.util.function.Supplier;

public class Room {

    private static final String RESERVED = "reserved";

    private String guest;

    // guests

    public String guestType() {
        return guest;
    }

    public void receive(String aGuestType) {
        // Room Occupied
        if (guest != null || RESERVED.equals(guest)) {
            throw new RuntimeException(Room.roomIsNotEmptyErrorDescription());
        } else {
            guest = aGuestType;
        }
    }

    public void receiveWithReservation(String aGuestType) {
        // Room Reserved
        if (RESERVED.equals(guest)) {
            guest = aGuestType;
        } else {
            throw new RuntimeException(Room.roomIsNotReservedErrorDescription());
        }
    }

    public void reserve() {
        // Room Occupied
        if (guest != null || RESERVED.equals(guest)) {
            throw new RuntimeException(Room.roomIsNotEmptyErrorDescription());
        } else {
            guest = RESERVED;
        }
    }

    // testing

    public boolean isAvailable() {
        return guest == null;
    }

    public boolean isOccupied() {
        return guest != null || RESERVED.equals(guest);
    }

    public boolean isReserved() {
        return RESERVED.equals(guest);
    }

    // accounting

    public Integer profitUsingIfAbsentGuestType(HashMap<String, Integer> aPriceList, Supplier<Integer> unknownGuestTypeBlock) {
        // Room Available
        if (guest == null) {
            return 0;
        }

        // Room Reserved
        if (RESERVED.equals(guest)) {
            return Collections.min(aPriceList.values()) / 2;
        }

        // Room Occupied
        if (guest != null || RESERVED.equals(guest)) {
            if (aPriceList.containsKey(guest)) {
                return aPriceList.get(guest);
            } else {
                return unknownGuestTypeBlock.get();
            }
        }

        return null;
    }

    public Integer lossUsingIfAbsentGuestType(HashMap<String, Integer> aPriceList, Supplier<Integer> unknownGuestTypeBlock) {
        // Not implemented yet: in the Smalltalk original this message does not exist in Room
        // (sending it raises MessageNotUnderstood). Java needs the method to compile the tests.
        throw new UnsupportedOperationException("Room does not understand lossUsingIfAbsentGuestType");
    }

    // error messages (class side)

    public static String roomIsNotEmptyErrorDescription() {
        return "Room is not empty.";
    }

    public static String roomIsNotReservedErrorDescription() {
        return "Room is not reserved.";
    }
}
package simshotels;

import java.util.ArrayList;
import java.util.Collections;
import java.util.HashMap;

public class Floor {

    private ArrayList<Room> rooms;
    private HashMap<String, Integer> prices;

    // testing

    public boolean isAvailable() {
        return totalRooms() == totalRoomsAvailable();
    }

    // accessing

    public ArrayList<Room> rooms() {
        return rooms;
    }

    // accounting

    public int totalLosses() {
        int total;

        total = 0;
        for (Room room : rooms) {
            if (room.isAvailable()) {
                total = total + Collections.max(prices.values());
            }
        }

        return total;
    }

    public int totalProfits() {
        int total;

        total = 0;
        for (Room room : rooms) {
            Integer roomTotal;
            if (room.isOccupied()) {
                roomTotal = room.profitUsingIfAbsentGuestType(prices, () -> {
                    Floor.signalUnknownGuestType();
                    return null;
                });
                total = total + roomTotal;
            }
        }

        return total;
    }

    // setters

    public void setNumberOfRooms(Number aNumberOfRooms) {
        Floor.assertIsPositiveIfFalse(aNumberOfRooms, () -> Floor.signalNumberOfRoomsMustBePositive());
        Floor.assertIsIntegerIfFalse(aNumberOfRooms, () -> Floor.signalNumberOfRoomsMustBeInteger());

        initializeRoomsWith(aNumberOfRooms);
    }

    public void setPrices(HashMap<String, Integer> aPriceList) {
        if (aPriceList.isEmpty()) {
            Floor.signalNoPrices();
        }

        for (Integer price : aPriceList.values()) {
            Floor.assertIsPositiveIfFalse(price, () -> Floor.signalPriceMustBePositive());
        }

        initializeWith(aPriceList);
    }

    // totals

    public int totalRooms() {
        return rooms.size();
    }

    public int totalRoomsAvailable() {
        int count = 0;
        for (Room room : rooms) {
            if (room.isAvailable()) {
                count = count + 1;
            }
        }
        return count;
    }

    public int totalRoomsOccupied() {
        int count = 0;
        for (Room room : rooms) {
            if (room.isOccupied()) {
                count = count + 1;
            }
        }
        return count;
    }

    public int totalRoomsReserved() {
        int count = 0;
        for (Room room : rooms) {
            if (room.isReserved()) {
                count = count + 1;
            }
        }
        return count;
    }

    // initialization

    private void initializeRoomsWith(Number aNumberOfRooms) {
        int ix;

        rooms = new ArrayList<>();

        ix = 1;
        while (ix <= aNumberOfRooms.intValue()) {
            rooms.add(new Room());
            ix = ix + 1;
        }
    }

    private void initializeWith(HashMap<String, Integer> aPriceList) {
        prices = aPriceList;
    }

    // assertions (class side)

    public static void assertIsIntegerIfFalse(Number aNumber, Runnable signalsBlock) {
        if (!(aNumber instanceof Integer)) {
            signalsBlock.run();
        }
    }

    public static void assertIsPositiveIfFalse(Number aNumber, Runnable signalsBlock) {
        if (!(aNumber.doubleValue() > 0)) {
            signalsBlock.run();
        }
    }

    // error messages (class side)

    public static String numberOfRoomsMustBeIntegerErrorDescription() {
        return "Number of rooms must be integer";
    }

    public static String numberOfRoomsMustBePositiveErrorDescription() {
        return "The number of rooms must be positive";
    }

    public static String priceMustBeIntegerErrorDescription() {
        return "Price must be integer";
    }

    public static String priceMustBePositiveErrorDescription() {
        return "Price must be positive";
    }

    public static String pricesListCannotBeEmptyErrorDescription() {
        return "Prices List must not be empty";
    }

    public static String unknownGuestTypeErrorDescription() {
        return "The guest type is unknown";
    }

    // exceptions (class side)

    public static void signalNoPrices() {
        throw new RuntimeException(Floor.pricesListCannotBeEmptyErrorDescription());
    }

    public static void signalNumberOfRoomsMustBeInteger() {
        throw new RuntimeException(Floor.numberOfRoomsMustBeIntegerErrorDescription());
    }

    public static void signalNumberOfRoomsMustBePositive() {
        throw new RuntimeException(Floor.numberOfRoomsMustBePositiveErrorDescription());
    }

    public static void signalPriceMustBeInteger() {
        throw new RuntimeException(Floor.priceMustBeIntegerErrorDescription());
    }

    public static void signalPriceMustBePositive() {
        throw new RuntimeException(Floor.priceMustBePositiveErrorDescription());
    }

    public static void signalUnknownGuestType() {
        throw new RuntimeException(Floor.unknownGuestTypeErrorDescription());
    }
}
package simshotels;

import java.util.ArrayList;

public class Hotel {

    private ArrayList<Floor> floors;
    private int availableRoomsCount;

    // initialization

    public Hotel() {
        availableRoomsCount = 0;
    }

    // accounting

    public int totalLosses() {
        int acc;

        acc = 0;
        for (Floor floor : floors) {
            acc = acc + floor.totalLosses();
        }

        return acc;
    }

    public int totalProfits() {
        int acc;

        acc = 0;
        for (Floor floor : floors) {
            acc = acc + floor.totalProfits();
        }

        return acc;
    }

    // setters

    public Hotel setFloors(ArrayList<Floor> aFloorsCollection) {
        Hotel.assertHaveFloors(aFloorsCollection);

        floors = aFloorsCollection;

        availableRoomsCount = totalRooms();

        return this;
    }

    // totals

    public int totalRooms() {
        int ix;
        int acc;

        acc = 0;

        ix = 1;
        while (ix <= floors.size()) {
            Floor floor;
            int jx;
            floor = floors.get(ix - 1);

            jx = 1;
            while (jx <= floor.rooms().size()) {
                acc = acc + 1;

                jx = jx + 1;
            }

            ix = ix + 1;
        }

        return acc;
    }

    public int totalRoomsAvailable() {
        return availableRoomsCount;
    }

    public int totalRoomsOccupied() {
        int ix;
        int acc;

        acc = 0;

        ix = 1;
        while (ix <= floors.size()) {
            Floor floor;
            int jx;
            floor = floors.get(ix - 1);

            jx = 1;
            while (jx <= floor.rooms().size()) {
                Room room;
                room = floor.rooms().get(jx - 1);
                if (room.isOccupied()) {
                    acc = acc + 1;
                }

                jx = jx + 1;
            }

            ix = ix + 1;
        }

        return acc;
    }

    public int totalRoomsReserved() {
        int ix;
        int acc;

        acc = 0;

        ix = 1;
        while (ix <= floors.size()) {
            Floor floor;
            int jx;
            floor = floors.get(ix - 1);

            jx = 1;
            while (jx <= floor.rooms().size()) {
                Room room;
                room = floor.rooms().get(jx - 1);
                if (room.isReserved()) {
                    acc = acc + 1;
                }

                jx = jx + 1;
            }

            ix = ix + 1;
        }

        return acc;
    }

    // testing

    public boolean isEmpty() {
        int ix;
        boolean acc;

        acc = true;

        ix = 1;
        while (ix <= floors.size()) {
            Floor floor;
            int jx;
            floor = floors.get(ix - 1);

            jx = 1;
            while (jx <= floor.rooms().size()) {
                Room room;
                room = floor.rooms().get(jx - 1);
                acc = acc && room.isAvailable();

                jx = jx + 1;
            }

            ix = ix + 1;
        }

        return acc;
    }

    // guests

    public void receiveAtFloorAtRoom(String aGuestType, int aFloorNumber, int aRoomNumber) {
        Floor floor;
        Room room;

        if (aFloorNumber < 1 || aFloorNumber > floors.size()) {
            Hotel.signalFloorNumberDoesNotExist();
        }
        floor = floors.get(aFloorNumber - 1);
        if (aRoomNumber < 1 || aRoomNumber > floor.rooms().size()) {
            Hotel.signalRoomNumberDoesNotExist();
        }
        room = floor.rooms().get(aRoomNumber - 1);

        room.receive(aGuestType);

        availableRoomsCount = availableRoomsCount - 1;
    }

    public void receiveWithReservationAtFloorAtRoom(String aGuestType, int aFloorNumber, int aRoomNumber) {
        Floor floor;
        Room room;

        if (aFloorNumber < 1 || aFloorNumber > floors.size()) {
            Hotel.signalFloorNumberDoesNotExist();
        }
        floor = floors.get(aFloorNumber - 1);
        if (aRoomNumber < 1 || aRoomNumber > floor.rooms().size()) {
            Hotel.signalRoomNumberDoesNotExist();
        }
        room = floor.rooms().get(aRoomNumber - 1);

        room.receiveWithReservation(aGuestType);
    }

    public void reserveRoomAtFloor(int aRoomNumber, int aFloorNumber) {
        Floor floor;
        Room room;

        if (aFloorNumber < 1 || aFloorNumber > floors.size()) {
            Hotel.signalFloorNumberDoesNotExist();
        }
        floor = floors.get(aFloorNumber - 1);
        if (aRoomNumber < 1 || aRoomNumber > floor.rooms().size()) {
            Hotel.signalRoomNumberDoesNotExist();
        }
        room = floor.rooms().get(aRoomNumber - 1);

        room.reserve();

        availableRoomsCount = availableRoomsCount - 1;
    }

    // assertions (class side)

    public static void assertHaveFloors(ArrayList<Floor> aFloorsCollection) {
        if (aFloorsCollection.isEmpty()) {
            Hotel.signalNoFloors();
        }
    }

    // error description (class side)

    public static String floorNumberDoesNotExistErrorDescription() {
        return "Floor number does not exist";
    }

    public static String noFloorsErrorDescription() {
        return "Cannot have a Hotel without floors";
    }

    public static String roomNumberDoesNotExistErrorDescription() {
        return "Room number does not exist";
    }

    // exceptions (class side)

    public static void signalFloorNumberDoesNotExist() {
        throw new RuntimeException(Hotel.floorNumberDoesNotExistErrorDescription());
    }

    public static void signalNoFloors() {
        throw new RuntimeException(Hotel.noFloorsErrorDescription());
    }

    public static void signalRoomNumberDoesNotExist() {
        throw new RuntimeException(Hotel.roomNumberDoesNotExistErrorDescription());
    }
}

